-- Time Card Edit -- authored as a DRAFT, 2026-11-13. Replaces JotForm 250193775451056.
-- APPLIED via psql 2026-11-13: form_id 3d5f93e9-1c78-4250-8c68-2e4881059472 (draft, unpublished).
-- Built by scripts/gen-time-card-edit.ts (strict + draft validated), in TEST mode:
-- every email goes to josh.copp@splashcarwashes.com. To go live, regenerate with
-- LIVE=1 (Wendy + site email + manager email), rebuild this file, re-run it, and
-- publish the new draft.
--
-- Re-runnable: upserts the forms row, creates a draft version only when there
-- is none, otherwise overwrites the existing draft schema.
--
--   slug time-card-edit   audience link-only   42 fields
--
-- Fields: site_number (scope field) -> site_name + site_email lookups;
-- employee (Employee field, roster of that site); edit_type (punch correction
-- 1 / 2 shifts, PTO 1-5 days) drives every conditional section; per shift:
-- date + original/corrected punch in/out; per PTO day: date + punch in/out;
-- notes; manager name + email; employee + manager signatures.
--
-- Workflow: one email step with the PDF attached -> "Sent to payroll".
--
-- After applying, the operator reviews and publishes from /admin/forms.

insert into public.forms
  (slug, title, description, audience, status, notify_webhook,
   turnstile_required, success_message, created_by, last_edited_by)
values
  ('time-card-edit',
   'Time Card Edit',
   'Record a punch correction or PTO for an employee. Payroll applies it in iSolved.',
   'link-only',
   'draft',
   true,
   false,
   'Thanks - the time card edit has been sent to payroll.',
   'f42882fd-ee5a-433e-b10b-713d5dff8a89',
   'f42882fd-ee5a-433e-b10b-713d5dff8a89')
on conflict (slug) do update
  set title = excluded.title,
      description = excluded.description,
      audience = excluded.audience,
      turnstile_required = excluded.turnstile_required,
      success_message = excluded.success_message,
      last_edited_at = now();

